import React, { useState } from "react";

export default function AuthPage() {
  const [isLogin, setIsLogin] = useState(true);

  return (
    <div id="auth" style={styles.container}>
      <div style={styles.card}>
        <h2 style={styles.title}>
          {isLogin ? "Welcome Back 👋" : "Create Account 🚀"}
        </h2>
        <p style={styles.subtitle}>
          {isLogin
            ? "Login to continue your DailyCode journey"
            : "Register to start your DailyCode journey"}
        </p>

        <form style={styles.form}>
          {!isLogin && (
            <input
              type="text"
              placeholder="Full Name"
              style={styles.input}
              required
            />
          )}
          <input
            type="email"
            placeholder="Email"
            style={styles.input}
            required
          />
          <input
            type="password"
            placeholder="Password"
            style={styles.input}
            required
          />
          {!isLogin && (
            <input
              type="password"
              placeholder="Confirm Password"
              style={styles.input}
              required
            />
          )}

          <button type="submit" style={styles.button}>
            {isLogin ? "Log In" : "Sign Up"}
          </button>
        </form>

        <p style={styles.footer}>
          {isLogin ? (
            <>
              Don’t have an account?{" "}
              <span
                style={styles.link}
                onClick={() => setIsLogin(false)}
              >
                Sign up
              </span>
            </>
          ) : (
            <>
              Already have an account?{" "}
              <span
                style={styles.link}
                onClick={() => setIsLogin(true)}
              >
                Log in
              </span>
            </>
          )}
        </p>
      </div>
    </div>
  );
}

const styles = {
  container: {
    height: "100vh",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    background: "linear-gradient(135deg, #0f172a, #1e3a8a)",
    fontFamily: "sans-serif",
    padding: "1rem",
  },

  card: {
    background: "rgba(255, 255, 255, 0.1)",
    backdropFilter: "blur(12px)",
    borderRadius: "16px",
    padding: "2rem",
    width: "100%",
    maxWidth: "400px",
    color: "white",
    boxShadow: "0 8px 32px rgba(0,0,0,0.3)",
    textAlign: "center",
  },

  title: {
    fontSize: "1.8rem",
    fontWeight: "bold",
    marginBottom: "0.5rem",
    color: "#38bdf8",
  },

  subtitle: {
    fontSize: "0.95rem",
    marginBottom: "1.5rem",
    color: "#e5e7eb",
  },

  form: {
    display: "flex",
    flexDirection: "column",
    gap: "1rem",
  },

  input: {
    padding: "0.8rem",
    borderRadius: "8px",
    border: "none",
    outline: "none",
    fontSize: "1rem",
    background: "rgba(255,255,255,0.2)",
    color: "white",
    transition: "0.3s",
  },

  button: {
    padding: "0.9rem",
    borderRadius: "8px",
    border: "none",
    background: "linear-gradient(135deg, #38bdf8, #2563eb)",
    color: "white",
    fontSize: "1rem",
    fontWeight: "bold",
    cursor: "pointer",
    transition: "0.3s",
  },

  footer: {
    marginTop: "1.5rem",
    fontSize: "0.9rem",
    color: "#d1d5db",
  },

  link: {
    color: "#38bdf8",
    textDecoration: "none",
    fontWeight: "bold",
    cursor: "pointer",
  },
};
